#!/usr/bin/env python3
"""
Installer for Phase 10 (PR #13): Model Context Protocol (MCP) Dynamic Subsystem
===============================================================================
This script creates/updates all files for dream/mcp/ and its comprehensive test suite.
Run this script from the root of your Dream repository:
    python apply_pr13.py
"""

import base64
import json
from pathlib import Path

B64_PAYLOAD = ""

def main():
    root = Path.cwd()
    print("🚀 Applying Phase 10: Model Context Protocol (MCP) Subsystem (dream/mcp/)...")
    raw_bytes = base64.b64decode(B64_PAYLOAD.encode("ascii"))
    files = json.loads(raw_bytes.decode("utf-8"))
    for rel_path, content in files.items():
        dest = root / rel_path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf-8")
        print(f"  ✅ Created/Updated: {rel_path}")
    print("\n🎉 PR #13 files successfully installed!")
    print("Run tests with: pytest tests/test_mcp_full_system.py tests/test_mcp.py")

if __name__ == "__main__":
    main()
